# compressed so it fits Oracle's size limit. Generated by pack-cloud-init.sh;
# CI checks that the two match. The SHA-256 below is setup-node.sh's.
#
# OPTIONAL: put your MetaMask address between the quotes to receive
# 1,000,000 test ZETAPHY at genesis (public address only, never a private key).
OWNER_EVM_ADDRESS=""

set -euo pipefail
f=/root/zetaphy-setup-node.sh
